"""Tests for scripts/ci/check_dev_container_locks.py: the x86_64 and aarch64 dev-container locks
must pin the same versions (the committed locks are checked too, so a lock bump that leaves one
architecture behind fails CI)."""

import subprocess
import sys
from pathlib import Path

from conftest import REPO_ROOT

SCRIPT = REPO_ROOT / "scripts" / "ci" / "check_dev_container_locks.py"
HASH = "a" * 64


def lock(path: Path, platform: str, pins: dict, unhashed=()) -> Path:
    lines = [
        "# This file was autogenerated by uv via the following command:",
        f"#    uv pip compile --generate-hashes --python-version 3.12 --python-platform {platform} "
        f"--output-file {path.name} requirements-dev-container.in",
    ]
    for name, version in pins.items():
        if name in unhashed:
            lines.append(f"{name}=={version}")
        else:
            lines += [f"{name}=={version} \\", f"    --hash=sha256:{HASH}"]
        lines.append("    # via something")
    path.write_text("\n".join(lines) + "\n")
    return path


class Locks:
    def __init__(self, tmp_path: Path):
        self.dir = tmp_path
        self.pins = {"numpy": "2.1.3", "Pillow": "12.2.0", "ruamel_yaml": "0.18.0"}
        (tmp_path / "requirements-dev-container.in").write_text(
            "# source\nnumpy==2.1.3\npillow==12.2.0  # inline comment\nzarr>=3.4.1,<3.5\n"
        )

    def run(self, x86=None, aarch64=None, **kw):
        x = lock(
            self.dir / "requirements-dev-container.txt",
            kw.get("x86_platform", "x86_64-unknown-linux-gnu"),
            self.pins if x86 is None else x86,
            kw.get("x86_unhashed", ()),
        )
        a = lock(
            self.dir / "requirements-dev-container-aarch64.txt",
            kw.get("aarch64_platform", "aarch64-unknown-linux-gnu"),
            self.pins if aarch64 is None else aarch64,
            kw.get("aarch64_unhashed", ()),
        )
        res = subprocess.run(
            [
                sys.executable,
                str(SCRIPT),
                "--x86",
                str(x),
                "--aarch64",
                str(a),
                "--in",
                str(self.dir / "requirements-dev-container.in"),
            ],
            capture_output=True,
            text=True,
        )
        res.output = res.stdout + res.stderr
        return res


def test_the_committed_locks_agree():
    res = subprocess.run([sys.executable, str(SCRIPT)], capture_output=True, text=True)
    assert res.returncode == 0, res.stderr
    assert "pin the same versions" in res.stdout


def test_equal_locks_pass(tmp_path):
    res = Locks(tmp_path).run()
    assert res.returncode == 0, res.output


def test_a_version_that_differs_between_the_locks_fails_naming_the_package(tmp_path):
    locks = Locks(tmp_path)
    res = locks.run(aarch64={**locks.pins, "ruamel_yaml": "0.18.1"})
    assert res.returncode == 1
    assert "ruamel-yaml: x86_64 pins 0.18.0, aarch64 pins 0.18.1" in res.output


def test_names_are_compared_after_normalisation(tmp_path):
    locks = Locks(tmp_path)
    res = locks.run(
        aarch64={"numpy": "2.1.3", "pillow": "12.2.0", "ruamel.yaml": "0.18.0"}
    )
    assert res.returncode == 0, res.output


def test_a_platform_only_package_is_reported_not_failed(tmp_path):
    locks = Locks(tmp_path)
    res = locks.run(aarch64={**locks.pins, "onlyarm": "1.0"})
    assert res.returncode == 0, res.output
    assert "only in the aarch64 lock: onlyarm" in res.output


def test_a_pin_of_the_in_file_must_be_in_both_locks(tmp_path):
    """A hollow lock shares no packages with the other, so only the .in file catches it."""
    locks = Locks(tmp_path)
    res = locks.run(aarch64={"onlyarm": "1.0"})
    assert res.returncode == 1
    assert "numpy==2.1.3, aarch64 lock has None" in res.output
    # a range in the .in file (zarr>=...) is not a strict pin, so it is not required
    assert "zarr" not in res.output


def test_a_stale_in_file_pin_fails(tmp_path):
    locks = Locks(tmp_path)
    res = locks.run(
        x86={**locks.pins, "numpy": "2.2.0"}, aarch64={**locks.pins, "numpy": "2.2.0"}
    )
    assert res.returncode == 1
    assert "pins numpy==2.1.3, x86_64 lock has 2.2.0" in res.output


def test_a_pin_without_a_hash_fails(tmp_path):
    res = Locks(tmp_path).run(aarch64_unhashed=("numpy",))
    assert res.returncode == 1
    assert "without a sha256 hash, first numpy" in res.output


def test_a_lock_compiled_for_the_wrong_platform_fails(tmp_path):
    res = Locks(tmp_path).run(aarch64_platform="x86_64-unknown-linux-gnu")
    assert res.returncode == 1
    assert "expected aarch64-unknown-linux-gnu" in res.output


def test_a_missing_file_is_a_usage_error(tmp_path):
    res = subprocess.run(
        [sys.executable, str(SCRIPT), "--x86", str(tmp_path / "nope.txt")],
        capture_output=True,
        text=True,
    )
    assert res.returncode == 2 and "missing file" in res.stderr
